int main() {
    // Test case 1: Normal case - valid packet with proper offset and data_size
    unsigned char packet1[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};
    int result1 = parse_network_packet(packet1, sizeof(packet1), 2, 3);
    printf("Test 1 - Normal case: returned %d\n", result1);

    // Test case 2: Edge case - offset at beginning of packet
    unsigned char packet2[] = {0xFF, 0xFE, 0xFD, 0xFC};
    int result2 = parse_network_packet(packet2, sizeof(packet2), 0, 2);
    printf("Test 2 - Offset at beginning: returned %d\n", result2);

    // Test case 3: Edge case - offset at end of packet
    unsigned char packet3[] = {0x10, 0x20, 0x30};
    int result3 = parse_network_packet(packet3, sizeof(packet3), 2, 1);
    printf("Test 3 - Offset at end: returned %d\n", result3);

    // Test case 4: Edge case - zero data_size
    unsigned char packet4[] = {0xAA, 0xBB, 0xCC};
    int result4 = parse_network_packet(packet4, sizeof(packet4), 1, 0);
    printf("Test 4 - Zero data_size: returned %d\n", result4);

    // Test case 5: Edge case - offset equals packet length (should be invalid)
    unsigned char packet5[] = {0x01, 0x02};
    int result5 = parse_network_packet(packet5, sizeof(packet5), 2, 1);
    printf("Test 5 - Offset equals packet length: returned %d\n", result5);

    // Test case 6: Large packet test
    unsigned char packet6[100];
    for(int i = 0; i < 100; i++) {
        packet6[i] = i % 256;
    }
    int result6 = parse_network_packet(packet6, 100, 10, 20);
    printf("Test 6 - Large packet: returned %d\n", result6);

    // Test case 7: Single byte packet
    unsigned char packet7[] = {0x55};
    int result7 = parse_network_packet(packet7, sizeof(packet7), 0, 1);
    printf("Test 7 - Single byte packet: returned %d\n", result7);

    printf("Functional tests completed.\n");
    return 0;
}

